DROP TABLE IF EXISTS `ey_search_word`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ey_search_word` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `word` varchar(255) DEFAULT '' COMMENT '关键词',
  `searchNum` int(11) DEFAULT '1' COMMENT '搜索次数',
  `resultNum` int(11) DEFAULT '0' COMMENT '搜索结果数量',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序号',
  `lang` varchar(30) DEFAULT 'cn' COMMENT '语言标识',
  `add_time` int(11) DEFAULT '0' COMMENT '新增时间',
  `update_time` int(11) DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `word` (`word`)
) ENGINE=MyISAM AUTO_INCREMENT=4169 DEFAULT CHARSET=utf8 COMMENT='搜索词统计表';
/*!40101 SET character_set_client = @saved_cs_client */;

