INSERT INTO `ey_setting` VALUES (1,'adminlogin_427d1aac31a93d744edd637f1fbbf00c','0','adminlogin','cn',1793699243),(2,'adminlogin_a62896d354440964bb1db242596917b1','0','adminlogin','cn',1793699243),(3,'adminlogin_99ae1cc546e0ed202a83693c75f1afe0','0','adminlogin','cn',1793699243),(4,'ask_ques_steps','1、写问题标题，描述具体现象。杜绝 “求救，大佬，小白…” 等和问题无关的词汇。\r\n2、选择问题的分类，选择正确的内容分类，能更快的得到其他人的回复。\r\n3、遇到的问题比较急需解决，可以给问题悬赏一定的金额报酬，能让更多同行参与进来出谋策划，从中选择自己心仪的答案。\r\n4、写问题内容详细描述你碰到的困难，写清楚你尝试了什么方法，错误代码，软件的版本等，更容易得到答案。\r\n5、点击发布。','ask','cn',1666617494),(5,'admin_logic_1649299958','1','syn','cn',1666617494),(6,'system_old_product_attr','0','system','cn',1666617494),(7,'syn_admin_logic_1625725290','1','syn','cn',1666617494),(8,'syn_admin_logic_1629252424','1','syn','cn',1666617494),(9,'admin_logic_1634204189','1','syn','cn',1666617494),(10,'admin_logic_1634280892','1','syn','cn',1666617494),(11,'admin_logic_1635326854','1','syn','cn',1666617494),(12,'admin_logic_1635389623','1','syn','cn',1666617494),(13,'admin_logic_1636875693','1','syn','cn',1666617494),(14,'admin_logic_1637033990','1','syn','cn',1666617494),(15,'admin_logic_1640918327','1','syn','cn',1666617494),(16,'admin_logic_1638857408','1','syn','cn',1666617494),(17,'admin_logic_1643352860','2','syn','cn',1666617494),(18,'admin_logic_1643352862','1','syn','cn',1666617494),(19,'admin_logic_1643352863','1','syn','cn',1666617494),(20,'security_askanswer_list','[\"\\u60a8\\u5e38\\u7528\\u7684\\u624b\\u673a\\u53f7\\u7801\\u662f\\uff1f\",\"\\u60a8\\u5e38\\u7528\\u7684\\u7535\\u5b50\\u90ae\\u7bb1\\u662f\\uff1f\",\"\\u60a8\\u771f\\u5b9e\\u7684\\u59d3\\u540d\\u662f\\uff1f\",\"\\u60a8\\u521d\\u4e2d\\u5b66\\u6821\\u540d\\u662f\\uff1f\",\"\\u60a8\\u7684\\u51fa\\u751f\\u5730\\u540d\\u662f\\uff1f\",\"\\u60a8\\u914d\\u5076\\u7684\\u59d3\\u540d\\u662f\\uff1f\",\"\\u60a8\\u7684\\u8eab\\u4efd\\u8bc1\\u53f7\\u540e\\u516b\\u4f4d\\u662f\\uff1f\",\"\\u60a8\\u9ad8\\u4e2d\\u73ed\\u4e3b\\u4efb\\u7684\\u540d\\u5b57\\u662f\\uff1f\",\"\\u60a8\\u521d\\u4e2d\\u73ed\\u4