INSERT INTO `ey_sql_cache_table` VALUES (1,'ArchivesMaxID','211','494a17e43cff13eeb4b9c9837c29026c','SELECT MAX(aid) AS tp_max FROM `ey_archives` LIMIT 1',1793254869,1793254869),(2,'|model|all|count|','{\"1\":{\"channel\":1,\"total\":187},\"6\":{\"channel\":6,\"total\":4}}','d5ac17fe5649c6d04f4b174c42f2d535','SELECT channel, count(aid) as total FROM `ey_archives` WHERE  `lang` = \'cn\'  AND `status` = 1  AND `is_del` = 0  AND (  (users_id = 0 OR (users_id > 0 AND arcrank >= 0)) ) GROUP BY `channel`',1793254871,1793254871),(3,'|arctype|all|count|','{\"3\":{\"typeid\":3,\"num\":32},\"4\":{\"typeid\":4,\"num\":6},\"12\":{\"typeid\":12,\"num\":9},\"13\":{\"typeid\":13,\"num\":12},\"16\":{\"typeid\":16,\"num\":66},\"17\":{\"typeid\":17,\"num\":12},\"18\":{\"typeid\":18,\"num\":11},\"19\":{\"typeid\":19,\"num\":12},\"20\":{\"typeid\":20,\"num\":12},\"24\":{\"typeid\":24,\"num\":15}}','9f6b5e62b9b8456535e5881c8b05072f','SELECT typeid, count(typeid) as num FROM `ey_archives` WHERE  `channel` IN (1,2,3,4,5,7,51)  AND `lang` = \'cn\'  AND `is_del` = 0  AND (  (users_id = 0 OR (users_id > 0 AND arcrank >= 0)) ) GROUP BY `typeid`',1793254895,1793254895);
/*!40000 ALTER TABLE `ey_sql_cache_table` ENABLE KEYS */;
UNLOCK TABLES;

